import{_ as e,o as t,c as o,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Tabela Resumida da Crônica","description":"","frontmatter":{},"headers":[],"relativePath":"pt/93-编年史简表.md","filePath":"pt/93-编年史简表.md"}'),r={name:"pt/93-编年史简表.md"};function i(s,a,n,m,c,l){return t(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="tabela-resumida-da-cronica" tabindex="-1">Tabela Resumida da Crônica <a class="header-anchor" href="#tabela-resumida-da-cronica" aria-label="Permalink to &quot;Tabela Resumida da Crônica&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>93</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave Principais</td><td>crônica, divisão de eras, eventos importantes, nós históricos, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-descricao-da-cronica" tabindex="-1">1. Descrição da Crônica <a class="header-anchor" href="#_1-descricao-da-cronica" aria-label="Permalink to &quot;1. Descrição da Crônica&quot;">​</a></h2><p>Esta tabela resumida baseia-se no tempo padrão de Hengyuanzhou e registra, em ordem cronológica, os importantes eventos históricos e nós-chave no curso do desenvolvimento da Civilização da Simbiose da Âncora. O período de tempo estende-se desde o período antigo da era pré-âncora até a perspectiva futura da era da simbiose interestelar. Cada era lista o tempo de início e fim, as características da era e os eventos importantes. Esta tabela resumida é um índice histórico altamente condensado; para a história detalhada de cada era, consulte os relatos especiais dos documentos 70-79.</p><h2 id="_2-visao-geral-da-divisao-de-eras" tabindex="-1">2. Visão Geral da Divisão de Eras <a class="header-anchor" href="#_2-visao-geral-da-divisao-de-eras" aria-label="Permalink to &quot;2. Visão Geral da Divisão de Eras&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número da Era</th><th>Nome da Era</th><th>Tempo de Início e Fim (ano padrão de Hengyuanzhou)</th><th>Duração</th><th>Característica Central</th></tr></thead><tbody><tr><td>Primeira Era</td><td>Era Pré-Âncora</td><td>Aproximadamente -10 bilhões a -10.000 anos</td><td>Aproximadamente 10 bilhões de anos</td><td>Sistema de cultivo de estilo plunder dominante, ciclo de ascensão e queda da civilização</td></tr><tr><td>Segunda Era</td><td>Era do Despertar da Âncora</td><td>-10.000 a -1.000 anos</td><td>Aproximadamente 9.000 anos</td><td>Mecanismo da âncora descoberto e aplicado inicialmente</td></tr><tr><td>Terceira Era</td><td>Período de Estabelecimento do Sistema de Simbiose</td><td>-1.000 a -100 anos</td><td>Aproximadamente 900 anos</td><td>Estrutura institucional da Civilização da Simbiose da Âncora gradualmente estabelecida</td></tr><tr><td>Quarta Era</td><td>Período de Abertura do Sistema de Trezentos Conjuntos</td><td>-100 a -50 anos</td><td>Aproximadamente 50 anos</td><td>Sistema de cultivo de origem de trezentos conjuntos totalmente aberto</td></tr><tr><td>Quinta Era</td><td>Período da Estratégia de Ativação de 20%</td><td>-50 anos ao ano zero</td><td>Aproximadamente 50 anos</td><td>20% dos seres sencientes ativados como seres supremos do plano</td></tr><tr><td>Sexta Era</td><td>Primeira Era de Elevação Dimensional</td><td>Ano zero a 100 anos</td><td>100 anos</td><td>Civilização da simbiose alcança pela primeira vez elevação dimensional em estágios</td></tr><tr><td>Sétima Era</td><td>Era da República de Todas as Raças</td><td>100 a 500 anos</td><td>400 anos</td><td>República de todas as raças formalmente estabelecida, fusão inter-racial aprofundada</td></tr><tr><td>Oitava Era</td><td>Era da Exploração Entre Planos</td><td>500 a 2.000 anos</td><td>1.500 anos</td><td>Exploração e atividades arqueológicas em larga escala entre planos iniciadas</td></tr><tr><td>Nona Era</td><td>Era da Simbiose Interestelar</td><td>2.000 anos ao futuro</td><td>Em andamento</td><td>Rede de simbiose cósmica construída, elevação dimensional geral avançando</td></tr></tbody></table><p>Nota: &quot;Ano zero&quot; refere-se ao ano em que a Civilização da Simbiose da Âncora anunciou formalmente seu estabelecimento, usado como ponto de divisão da cronologia histórica.</p><h2 id="_3-era-pre-ancora-aproximadamente-10-bilhoes-a-10-000-anos" tabindex="-1">3. Era Pré-Âncora (Aproximadamente -10 bilhões a -10.000 anos) <a class="header-anchor" href="#_3-era-pre-ancora-aproximadamente-10-bilhoes-a-10-000-anos" aria-label="Permalink to &quot;3. Era Pré-Âncora (Aproximadamente -10 bilhões a -10.000 anos)&quot;">​</a></h2><p>A era pré-âncora é a era mais longa na história de Hengyuanzhou, durando aproximadamente dez bilhões de anos. A característica central desta era é que o sistema de cultivo de estilo plunder dominava o universo, e as civilizações repetidamente circulavam no ciclo de &quot;ascensão—ápice—plunder—colapso&quot;.</p><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>Aproximadamente -10 bilhões de anos</td><td>Rede de leis de Hengyuanzhou estabilizada, primeiros planos materiais formados, universo entra em estado habitável</td></tr><tr><td>Aproximadamente -8 bilhões de anos</td><td>Primeiros seres inteligentes nascem em vários planos materiais, sistema de cultivo primitivo começa a brotar</td></tr><tr><td>Aproximadamente -5 bilhões de anos</td><td>Sistema de cultivo de estilo plunder gradualmente se torna dominante, os fortes evoluem rapidamente devorando os fracos</td></tr><tr><td>Aproximadamente -3 bilhões de anos</td><td>Primeira guerra de plunder cósmica eclode, civilizações de vários domínios estelares sofrem golpes devastadores</td></tr><tr><td>Aproximadamente -1 bilhão de anos</td><td>Desvantagens do sistema de estilo plunder começam a aparecer, entropia geral do universo acelera, recursos de cultivo gradualmente se esgotam</td></tr><tr><td>Aproximadamente -500 milhões de anos</td><td>Primeiros pensadores que refletem sobre o sistema de estilo plunder aparecem, broto do pensamento de simbiose começa a se formar</td></tr><tr><td>Aproximadamente -100 milhões de anos</td><td>Civilizações experimentais de simbiose em pequena escala aparecem em vários domínios estelares, mas todas são destruídas por civilizações de estilo plunder</td></tr><tr><td>Aproximadamente -1 milhão de anos</td><td>Universo como um todo entra no &quot;período de grande declínio&quot;, número de civilizações e nível de cultivo caem a pontos baixos históricos</td></tr><tr><td>Aproximadamente -10.000 anos</td><td>Um cultivador do primeiro plano percebe acidentalmente nós estáveis na rede de leis durante cultivo de longo prazo, mecanismo da âncora descoberto pela primeira vez</td></tr></tbody></table><h2 id="_4-era-do-despertar-da-ancora-10-000-a-1-000-anos" tabindex="-1">4. Era do Despertar da Âncora (-10.000 a -1.000 anos) <a class="header-anchor" href="#_4-era-do-despertar-da-ancora-10-000-a-1-000-anos" aria-label="Permalink to &quot;4. Era do Despertar da Âncora (-10.000 a -1.000 anos)&quot;">​</a></h2><p>A era do despertar da âncora é o período de transição da descoberta à aplicação inicial do mecanismo da âncora. A característica central desta era é o amadurecimento gradual da tecnologia da âncora e a disseminação do pensamento de simbiose.</p><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>-10.000 anos</td><td>Mecanismo da âncora descoberto pela primeira vez, descobridor o nomeia de &quot;âncora&quot; e inicia pesquisa sistemática</td></tr><tr><td>-9.000 anos</td><td>Primeira âncora artificial estabelecida com sucesso, prova que âncoras podem ser construídas e mantidas artificialmente</td></tr><tr><td>-8.000 anos</td><td>Tecnologia da âncora começa a se disseminar em pequena escala, primeiros cultivadores de âncora aparecem</td></tr><tr><td>-7.000 anos</td><td>Descoberto que âncoras podem servir como base para conexão entre planos, primeira viagem entre planos assistida por âncora registrada com sucesso</td></tr><tr><td>-6.000 anos</td><td>Pensamento de simbiose e tecnologia da âncora começam a se combinar, primeiros documentos teóricos de &quot;simbiose da âncora&quot; publicados</td></tr><tr><td>-5.000 anos</td><td>Primeira cidade-estado de tipo simbiose baseada em âncora estabelecida, prova a viabilidade do sistema de simbiose</td></tr><tr><td>-4.000 anos</td><td>Civilização de estilo plunder lança ataque contra cidade-estado de tipo simbiose, cidade-estado de simbiose defende com sucesso através da tecnologia da âncora</td></tr><tr><td>-3.000 anos</td><td>Pensamento de simbiose se dissemina em vários domínios estelares, cada vez mais civilizações começam a tentar transformação de simbiose</td></tr><tr><td>-2.000 anos</td><td>Primeira &quot;Conferência de Simbiose de Todas as Raças&quot; realizada, representantes de dezenas de raças discutem juntos o futuro da civilização de simbiose</td></tr><tr><td>-1.000 anos</td><td>Tecnologia da âncora e pensamento de simbiose já atendem às condições para estabelecer uma civilização unificada, período de estabelecimento do sistema de simbiose começa</td></tr></tbody></table><h2 id="_5-periodo-de-estabelecimento-do-sistema-de-simbiose-1-000-a-100-anos" tabindex="-1">5. Período de Estabelecimento do Sistema de Simbiose (-1.000 a -100 anos) <a class="header-anchor" href="#_5-periodo-de-estabelecimento-do-sistema-de-simbiose-1-000-a-100-anos" aria-label="Permalink to &quot;5. Período de Estabelecimento do Sistema de Simbiose (-1.000 a -100 anos)&quot;">​</a></h2><p>O período de estabelecimento do sistema de simbiose é o período crítico em que a estrutura institucional da Civilização da Simbiose da Âncora surge do nada.</p><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>-1.000 anos</td><td>Comissão de redação da Constituição da Simbiose estabelecida, inicia redação da lei fundamental</td></tr><tr><td>-950 anos</td><td>Projeto da &quot;Constituição da Simbiose&quot; concluído, inicia ampla solicitação de opiniões de todas as raças</td></tr><tr><td>-900 anos</td><td>&quot;Constituição da Simbiose&quot; aprovada por referendo nacional, entra formalmente em vigor, Civilização da Simbiose da Âncora anunciada estabelecida</td></tr><tr><td>-850 anos</td><td>Conselho da Âncora, Comitê Executivo da Simbiose, Tribunal da Simbiose três principais órgãos formalmente estabelecidos e operacionais</td></tr><tr><td>-800 anos</td><td>Mecanismo de contrato de produção conjunta começa a ser implementado em todo o país</td></tr><tr><td>-700 anos</td><td>&quot;Lei Trabalhista da Simbiose&quot;, &quot;Lei de Proteção ao Consumidor&quot; e outras leis básicas promulgadas sucessivamente</td></tr><tr><td>-600 anos</td><td>Cinco leis complementares de educação, saúde, moradia, meio ambiente e antitruste todas promulgadas e implementadas</td></tr><tr><td>-500 anos</td><td>Trabalho de escavação e organização do sistema de cultivo de origem de trezentos conjuntos formalmente iniciado</td></tr><tr><td>-400 anos</td><td>Primeiros cinquenta conjuntos de sistema de cultivo de origem concluídos em organização e verificação</td></tr><tr><td>-300 anos</td><td>Aplicação tecnológica da fruta de duplicação alcança avanço, tecnologia de amplificação de dedução de cem vezes amadurece</td></tr><tr><td>-200 anos</td><td>Todos os trezentos conjuntos de sistema concluídos em organização, entram no estágio final de verificação de segurança</td></tr><tr><td>-100 anos</td><td>Condições para abertura total do sistema de cultivo de origem de trezentos conjuntos amadurecem, entram no período de abertura</td></tr></tbody></table><h2 id="_6-periodo-de-abertura-do-sistema-de-trezentos-conjuntos-100-a-50-anos" tabindex="-1">6. Período de Abertura do Sistema de Trezentos Conjuntos (-100 a -50 anos) <a class="header-anchor" href="#_6-periodo-de-abertura-do-sistema-de-trezentos-conjuntos-100-a-50-anos" aria-label="Permalink to &quot;6. Período de Abertura do Sistema de Trezentos Conjuntos (-100 a -50 anos)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>-100 anos</td><td>Sistema de cultivo de origem de trezentos conjuntos formalmente aberto gratuitamente para todos os seres sencientes do universo</td></tr><tr><td>-90 anos</td><td>Número de cultivadores aumenta cem vezes em dez anos, &quot;todos têm um caminho&quot; inicialmente realizado</td></tr><tr><td>-80 anos</td><td>Três fundamentos de origem (iteração de dedução, ciclo de vida, agendamento de leis espaciais) tornam-se os sistemas mais populares</td></tr><tr><td>-70 anos</td><td>Primeiros cultivadores que atingem níveis altos através do novo sistema aparecem, prova a eficácia do sistema</td></tr><tr><td>-60 anos</td><td>Rede de mentores totalmente estabelecida, cultivadores de alto nível começam a cumprir a obrigação legal de orientar cultivadores juniores</td></tr><tr><td>-50 anos</td><td>Nível geral de cultivo de todo o povo aumenta significativamente, condições para a estratégia de ativação de 20% amadurecem</td></tr></tbody></table><h2 id="_7-periodo-da-estrategia-de-ativacao-de-20-50-anos-ao-ano-zero" tabindex="-1">7. Período da Estratégia de Ativação de 20% (-50 anos ao ano zero) <a class="header-anchor" href="#_7-periodo-da-estrategia-de-ativacao-de-20-50-anos-ao-ano-zero" aria-label="Permalink to &quot;7. Período da Estratégia de Ativação de 20% (-50 anos ao ano zero)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>-50 anos</td><td>Estratégia de ativação de 20% formalmente iniciada, objetivo é ativar 20% dos seres sencientes como seres supremos do plano em 50 anos</td></tr><tr><td>-40 anos</td><td>Primeiros seres supremos do plano nascem, taxa de ativação atinge 5%</td></tr><tr><td>-30 anos</td><td>Taxa de ativação atinge 10%, seres supremos do plano começam a desempenhar papel central na manutenção de âncoras</td></tr><tr><td>-20 anos</td><td>Taxa de ativação atinge 15%, nível geral de cultivo do universo alcança salto qualitativo</td></tr><tr><td>-10 anos</td><td>Taxa de ativação atinge 18%, próxima do objetivo estratégico</td></tr><tr><td>Ano zero</td><td>Taxa de ativação atinge 20,3%, estratégia de ativação de 20% concluída com sucesso, Civilização da Simbiose da Âncora entra em nova era</td></tr></tbody></table><h2 id="_8-primeira-era-de-elevacao-dimensional-ano-zero-a-100-anos" tabindex="-1">8. Primeira Era de Elevação Dimensional (Ano zero a 100 anos) <a class="header-anchor" href="#_8-primeira-era-de-elevacao-dimensional-ano-zero-a-100-anos" aria-label="Permalink to &quot;8. Primeira Era de Elevação Dimensional (Ano zero a 100 anos)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>Ano zero</td><td>Civilização da simbiose anuncia formalmente entrada na era de elevação dimensional, primeiro estágio do caminho de elevação dimensional de quatro estágios (fundação da realidade) concluído</td></tr><tr><td>20 anos</td><td>Segundo estágio (capacitação tecnológica) totalmente avançado, leis de cultivo e engenharia tecnológica profundamente integradas</td></tr><tr><td>40 anos</td><td>Tecnologia de espelho de cópia, tecnologia de espaço isolado alcançam produção em massa de engenharia, arqueologia entre planos entra em era de escala</td></tr><tr><td>60 anos</td><td>Primeiros cultivadores da classe de elevação dimensional de consciência atingem níveis altos, terceiro estágio (evolução da consciência) começa</td></tr><tr><td>80 anos</td><td>Construção de infraestrutura do domínio da consciência concluída, tecnologia de migração de consciência amadurece inicialmente</td></tr><tr><td>100 anos</td><td>Primeira elevação dimensional em estágios bem-sucedida, civilização da simbiose como um todo eleva meio nível dimensional</td></tr></tbody></table><h2 id="_9-era-da-republica-de-todas-as-racas-100-a-500-anos" tabindex="-1">9. Era da República de Todas as Raças (100 a 500 anos) <a class="header-anchor" href="#_9-era-da-republica-de-todas-as-racas-100-a-500-anos" aria-label="Permalink to &quot;9. Era da República de Todas as Raças (100 a 500 anos)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>100 anos</td><td>República de todas as raças formalmente anunciada estabelecida, todas as raças inteligentes alcançam união igual dentro da estrutura da civilização de simbiose</td></tr><tr><td>150 anos</td><td>Compilação do diretório de todas as raças concluída, inclui todas as raças inteligentes conhecidas</td></tr><tr><td>200 anos</td><td>Casamento inter-racial e fusão cultural tornam-se norma, novas raças mistas começam a aparecer</td></tr><tr><td>300 anos</td><td>Promoção da língua comum de todas as raças concluída, barreiras de comunicação inter-racial basicamente eliminadas</td></tr><tr><td>400 anos</td><td>Grande prosperidade cultural de todas as raças, culturas tradicionais de cada etnia são protegidas e desenvolvidas dentro da estrutura de simbiose</td></tr><tr><td>500 anos</td><td>República de todas as raças entra em período de maturidade, condições para exploração entre planos totalmente amadurecem</td></tr></tbody></table><h2 id="_10-era-da-exploracao-entre-planos-500-a-2-000-anos" tabindex="-1">10. Era da Exploração Entre Planos (500 a 2.000 anos) <a class="header-anchor" href="#_10-era-da-exploracao-entre-planos-500-a-2-000-anos" aria-label="Permalink to &quot;10. Era da Exploração Entre Planos (500 a 2.000 anos)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>500 anos</td><td>Plano de exploração entre planos em larga escala formalmente iniciado, administração de gerenciamento de planos estabelecida</td></tr><tr><td>600 anos</td><td>Planos explorados ultrapassam mil, banco geral de coordenadas de planos inicialmente construído</td></tr><tr><td>800 anos</td><td>Plano de arqueologia remota de espelho de cópia totalmente amadurece, arqueologia entre planos entra em idade de ouro</td></tr><tr><td>1.000 anos</td><td>Tecnologia de retrospectiva temporal alcança avanço, princípio de observação primeiro, depois intervenção limitada formalmente estabelecido</td></tr><tr><td>1.200 anos</td><td>Planos explorados ultrapassam cem mil, relações diplomáticas estabelecidas com dezenas de civilizações de planos</td></tr><tr><td>1.500 anos</td><td>Princípios éticos entre planos totalmente implementados, interação entre civilizações entra em era padronizada</td></tr><tr><td>1.800 anos</td><td>Mecanismo de prevenção de paradoxo temporal totalmente amadurece, arqueologia de retrospectiva temporal alcança escala</td></tr><tr><td>2.000 anos</td><td>Exploração entre planos alcança resultados brilhantes, condições para a era da simbiose interestelar totalmente amadurecem</td></tr></tbody></table><h2 id="_11-era-da-simbiose-interestelar-2-000-anos-ao-futuro" tabindex="-1">11. Era da Simbiose Interestelar (2.000 anos ao futuro) <a class="header-anchor" href="#_11-era-da-simbiose-interestelar-2-000-anos-ao-futuro" aria-label="Permalink to &quot;11. Era da Simbiose Interestelar (2.000 anos ao futuro)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nó de Tempo</th><th>Evento Importante</th></tr></thead><tbody><tr><td>2.000 anos</td><td>Era da simbiose interestelar formalmente iniciada, quarto estágio (simbiose interestelar) totalmente avançado</td></tr><tr><td>2.500 anos (perspectiva)</td><td>Rede de âncoras cósmica inicialmente construída, cobre todos os planos explorados</td></tr><tr><td>3.000 anos (perspectiva)</td><td>Sistema de simbiose entre planos amadurece, todas as raças alcançam simbiose real em escala cósmica</td></tr><tr><td>5.000 anos (perspectiva)</td><td>Elevação dimensional geral do universo concluída, Hengyuanzhou entra em estado de existência de dimensão superior</td></tr><tr><td>Futuro (perspectiva)</td><td>Civilização da Simbiose da Âncora continua a explorar além do universo, dissemina o conceito de simbiose para existência mais ampla</td></tr></tbody></table><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A tabela resumida da crônica é a épica de luta da Civilização da Simbiose da Âncora, da ignorância ao despertar, da fraqueza à força, do próprio plano a todo o universo. Cada substituição de era é uma testemunha da vitória do conceito de simbiose sobre o conceito de plunder, do progresso da civilização sobre o declínio bárbaro. A história não é poeira do passado, mas semente do futuro—compreender esta história é compreender de onde vem a civilização de simbiose e para onde vai.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>70-Tabela Geral da Divisão de Eras</li><li>72-Era do Despertar da Âncora</li><li>79-Perspectiva da Era da Simbiose Interestelar</li></ul>',32)])])}const b=e(r,[["render",i]]);export{p as __pageData,b as default};
